mapper.insert:
INSERT INTO dms_order_finance (order_id, order_no, pay_amount, refund_amount, net_pay_amount, product_cost, bonus_amount,
    company_share_amount, company_profit, risk_status, remark)
SELECT #{finance.orderId}, #{finance.orderNo}, #{finance.payAmount}, #{finance.refundAmount}, #{finance.netPayAmount},
    #{finance.productCost}, #{finance.bonusAmount}, #{finance.companyShareAmount}, #{finance.companyProfit},
    #{finance.riskStatus}, #{finance.remark}
FROM dms_shop_order scoped_order
WHERE scoped_order.id = #{finance.orderId}
  AND COALESCE(scoped_order.tenant_id, 1) = #{tenantId}

mapper.select:
SELECT COUNT(1) AS order_count, SUM(CASE WHEN finance.risk_status = 1 THEN 1 ELSE 0 END) AS risk_order_count, IFNULL(SUM(finance.pay_amount), 0) AS pay_amount, IFNULL(SUM(finance.refund_amount), 0) AS refund_amount, IFNULL(SUM(finance.net_pay_amount), 0) AS net_pay_amount, IFNULL(SUM(finance.product_cost), 0) AS product_cost, IFNULL(SUM(finance.bonus_amount), 0) AS bonus_amount, IFNULL(SUM(finance.company_share_amount), 0) AS company_share_amount, IFNULL(SUM(finance.company_profit), 0) AS company_profit FROM dms_order_finance finance INNER JOIN dms_shop_order shop_order ON shop_order.id = finance.order_id WHERE shop_order.pay_time IS NOT NULL AND COALESCE(shop_order.tenant_id, 1) = #{tenantId}
AND shop_order.pay_time >= #{startTime}
AND shop_order.pay_time < #{endTime}

SELECT DATE(shop_order.pay_time) AS stat_date, COUNT(1) AS order_count, SUM(CASE WHEN finance.risk_status = 1 THEN 1 ELSE 0 END) AS risk_order_count, IFNULL(SUM(finance.pay_amount), 0) AS pay_amount, IFNULL(SUM(finance.refund_amount), 0) AS refund_amount, IFNULL(SUM(finance.net_pay_amount), 0) AS net_pay_amount, IFNULL(SUM(finance.product_cost), 0) AS product_cost, IFNULL(SUM(finance.bonus_amount), 0) AS bonus_amount, IFNULL(SUM(finance.company_share_amount), 0) AS company_share_amount, IFNULL(SUM(finance.company_profit), 0) AS company_profit FROM dms_order_finance finance INNER JOIN dms_shop_order shop_order ON shop_order.id = finance.order_id WHERE shop_order.pay_time IS NOT NULL AND COALESCE(shop_order.tenant_id, 1) = #{tenantId}
AND shop_order.pay_time >= #{startTime}
AND shop_order.pay_time < #{endTime}
GROUP BY DATE(shop_order.pay_time) ORDER BY stat_date ASC
